import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.CXroN2RO.js";const c="/study/images/browser/atomics-lost-update.svg",s="/study/images/browser/atomics-wait-notify.svg",f=JSON.parse('{"title":"Web Workerと共有メモリの同期 — Atomics・競合・待機","description":"","frontmatter":{"title":"Web Workerと共有メモリの同期 — Atomics・競合・待機","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"二つのWorkerが同じ整数を更新するときの更新の取りこぼしと、Atomicsによる不可分な加算、フラグを使ったデータの受け渡しを図解する。","aliases":["Web Worker","Dedicated Worker","SharedArrayBuffer","共有メモリ","Atomics","Atomics.add","Atomics.load","Atomics.store","Atomics.wait","Atomics.notify","RMW","lost update","更新の取りこぼし","条件待ち"],"verification":"ECMAScriptのAtomics・メモリモデルとWHATWG HTMLのエージェントの定義に照合（2026-11-05）"}},"headers":[],"relativePath":"browser/shared-memory-atomics.md","filePath":"browser/shared-memory-atomics.md"}'),i={name:"browser/shared-memory-atomics.md"};function d(m,e,l,n,h,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="web-workerと共有メモリの同期-—-atomics・競合・待機" tabindex="-1">Web Workerと共有メモリの同期 — Atomics・競合・待機 <a class="header-anchor" href="#web-workerと共有メモリの同期-—-atomics・競合・待機" aria-label="Permalink to &quot;Web Workerと共有メモリの同期 — Atomics・競合・待機&quot;">​</a></h1><p>二つのWorkerが同じ <code>SharedArrayBuffer</code> に <code>Int32Array</code> のビューを作ると、別々のJavaScript実行環境から同じバイト列を読み書きできます。カウンターを一つ増やす場合でも、どの処理をまとめるかで結果が変わります。値を渡す場合は、受け取り側が読み始めてよい時点も決めます。ここでは整数一つの加算と、準備完了を知らせるフラグを使って、この二つを観察します。<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>、<a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a></p><h2 id="個々の読み書きが不可分でも更新を取りこぼす" tabindex="-1">個々の読み書きが不可分でも更新を取りこぼす <a class="header-anchor" href="#個々の読み書きが不可分でも更新を取りこぼす" aria-label="Permalink to &quot;個々の読み書きが不可分でも更新を取りこぼす&quot;">​</a></h2><p>共有カウンター <code>view[0]</code> を0から始めます。Worker AとBがそれぞれ <code>Atomics.load(view, 0)</code> で読んで、取得した値に1を足し、<code>Atomics.store(view, 0, old + 1)</code> で書き戻すとします。AとBの両方が先に読んだ場合、それぞれが持つ <code>old</code> は0です。両方の書き戻しが終わった時点のカウンターは1になります。この現象を<strong>更新の取りこぼし</strong>（lost update）と呼びます。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.load" target="_blank" rel="noreferrer">ECMAScriptのAtomics.load</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.store" target="_blank" rel="noreferrer">Atomics.store</a></p><p><code>Atomics.load</code> と <code>Atomics.store</code> はそれぞれ一つのアトミック操作です。二つの呼び出しの間には、別のWorkerの操作が入れます。実践では両方のWorkerの読み取りが終わってから書き戻しを指示し、取りこぼしが起きる順序を再現します。</p><h2 id="atomics-addで読み取りと書き戻しを一つにする" tabindex="-1">Atomics.addで読み取りと書き戻しを一つにする <a class="header-anchor" href="#atomics-addで読み取りと書き戻しを一つにする" aria-label="Permalink to &quot;Atomics.addで読み取りと書き戻しを一つにする&quot;">​</a></h2><p><code>Atomics.add(view, 0, 1)</code> は、同じ要素の現在値を読み、加算し、書き戻すところまでを一つのアトミック操作として扱います。この操作を <strong>read-modify-write</strong>（RMW）と呼びます。戻り値は<strong>加算前の値</strong>です。0から一度ずつ呼ぶと、一方は0を返して1を書き、もう一方は1を返して2を書きます。どちらのWorkerが0を返すかは実行順によります。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.add" target="_blank" rel="noreferrer">ECMAScriptのAtomics.add</a>、<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-memory-model-fundamentals" target="_blank" rel="noreferrer">メモリモデルの基本</a></p><figure class="study-figure"><img src="'+c+'" alt="別々のloadとstoreではWorker AとBがともに0を読み、ともに1を書き、結果は1になる。Atomics.addでは先のWorkerが0を返して1を書き、次のWorkerが1を返して2を書き、結果は2になる。" width="760" height="1000" loading="lazy"><figcaption>同じ初期値から、操作の単位を変えたときの結果を比べます。下段はAが先に加算した例です。<a href="/study/images/browser/atomics-lost-update.svg" target="_blank" rel="noopener noreferrer">更新の取りこぼしと不可分な加算を拡大</a></figcaption></figure><p><code>Atomics.add</code> がまとめるのは対象の一要素です。例えば「残数と消費数の合計は常に初期在庫に等しい」という条件を守りたいとき、残数を減らす操作と消費数を増やす操作を別々に実行すると、読み手が途中の組を観察できます。どの値を一緒に変更・観察するかを決め、同じロックで守るか、更新を担当するWorkerを一つにして状態をメッセージで渡すなどの設計を選びます。<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>、<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-shared-memory-guidelines" target="_blank" rel="noreferrer">ECMAScriptの共有メモリの指針</a></p><h2 id="データを書き、フラグを立ててから通知する" tabindex="-1">データを書き、フラグを立ててから通知する <a class="header-anchor" href="#データを書き、フラグを立ててから通知する" aria-label="Permalink to &quot;データを書き、フラグを立ててから通知する&quot;">​</a></h2><p>一回だけ整数42を渡す例を考えます。実践の <code>Int32Array</code> では、添字1（<code>Ready</code>）に準備フラグ、添字2（<code>Payload</code>）に受け渡すデータを置きます。フラグの初期値は0です。送り手のWorkerはデータを書き、<code>Atomics.store</code> でフラグを1にして、同じフラグ位置へ <code>Atomics.notify</code> を呼びます。受け手は <code>Atomics.load</code> でその1を読んでからデータを読みます。フラグに対する書き込みと、その1を読んだ操作が同期するので、データの書き込みが受け手の読み取りに先行します。実践では実行ごとに新しいバッファを用意し、データを一度だけ書き込みます。<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-synchronizes-with" target="_blank" rel="noreferrer">ECMAScriptのsynchronizes-with</a>、<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-happens-before" target="_blank" rel="noreferrer">happens-before</a></p><figure class="study-figure"><img src="'+s+'" alt="受け手のWorkerはフラグが0なら待機を試みる。送り手はデータを書いてフラグを1にしてから通知する。受け手は待機から戻ったらフラグを読み直し、1を確認してデータを読む。最初に0を読んだ後、waitの比較より先にフラグが1になった場合は待機せずに戻る。" width="760" height="1100" loading="lazy"><figcaption>通知で待機を解除し、フラグの値で読み取りの可否を判断します。<a href="/study/images/browser/atomics-wait-notify.svg" target="_blank" rel="noopener noreferrer">待機と通知の流れを拡大</a></figcaption></figure><h2 id="atomics-waitの戻り値とフラグを区別する" tabindex="-1">Atomics.waitの戻り値とフラグを区別する <a class="header-anchor" href="#atomics-waitの戻り値とフラグを区別する" aria-label="Permalink to &quot;Atomics.waitの戻り値とフラグを区別する&quot;">​</a></h2><p>受け手のWorkerは、フラグが0の間に <code>Atomics.wait(view, flagIndex, 0, timeoutMs)</code> を呼びます。 <code>wait</code> は同じ位置をもう一度検査し、期待した値と一致する場合だけ待機に入ります。待機先は、共有データブロック内の該当位置に対応する待機リストです。 <code>wait</code> と <code>notify</code> の対象に使うビューの型は <code>Int32Array</code> または <code>BigInt64Array</code> です。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.wait" target="_blank" rel="noreferrer">ECMAScriptのAtomics.wait</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-dowait" target="_blank" rel="noreferrer">DoWait</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.notify" target="_blank" rel="noreferrer">Atomics.notify</a></p><table tabindex="0"><thead><tr><th><code>Atomics.wait</code> の戻り値</th><th>何が起きたか</th></tr></thead><tbody><tr><td><code>&quot;ok&quot;</code></td><td>待機に入り、<code>Atomics.notify</code> で待機が解除された</td></tr><tr><td><code>&quot;not-equal&quot;</code></td><td><code>wait</code> の検査で値が期待値と異なり、待機に入らなかった</td></tr><tr><td><code>&quot;timed-out&quot;</code></td><td>待機時間が満了した</td></tr></tbody></table><p><code>Atomics.notify(view, flagIndex, 1)</code> の戻り値は、通知した待機者の数です。通知だけではフラグが変わらないので、受け手は待機から戻ったあとにフラグを読み直し、条件がそろうまで待ち直すか、制限時間で打ち切ります。最初の <code>load</code> と <code>wait</code> の間に送り手がフラグを1にした場合、<code>wait</code> の比較で <code>&quot;not-equal&quot;</code> が返ります。最初から1を読んだ場合は待機を省けます。待機者がまだいなければ <code>notify</code> は0を返し、フラグに書いた1が残ります。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-dowait" target="_blank" rel="noreferrer">ECMAScriptのDoWait</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.notify" target="_blank" rel="noreferrer">Atomics.notify</a></p><p>ブラウザのページ側のメインスレッドでは、<code>Atomics.wait</code> は <code>TypeError</code> になります。実践では、ページが二つのDedicated Workerに操作を指示します。待機中は受け手のWorkerが次のメッセージを処理できないので、もう一方のWorkerがデータとフラグを書いて通知します。<a href="https://html.spec.whatwg.org/multipage/webappapis.html#integration-with-the-javascript-agent-formalism" target="_blank" rel="noreferrer">WHATWG HTMLのエージェントの定義</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-dowait" target="_blank" rel="noreferrer">ECMAScriptのDoWait</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>公開ページのステップ実験では、操作の順番と値の変化を一つずつ追えます。実際のWorkerで動かすには、ページとWorkerが <code>SharedArrayBuffer</code> を共有できる配信環境が必要です。実践ページには、クロスオリジン分離に必要な応答ヘッダーを付けてローカルで配信する手順もあります。<a href="/study/practice/browser/atomics-observation.html">Workerの競合とAtomicsの待機・通知を観察する</a></p><p>複数の値を順番に受け渡し、読み終えた枠を使い回す例は、<a href="/study/browser/spsc-ring-buffer.html">リングバッファとSPSCキュー</a>で扱います。</p>',20)])])}const g=t(i,[["render",d]]);export{f as __pageData,g as default};
